package com.oms.order.service;

import com.oms.messaging.*;
import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.m;

class RefundIntakeMessageTest {
 static final String C="REFUND_MQ_VERIFY";static AnnotationConfigApplicationContext context;static OrderRepository repo;static MessageOutbox out;static JdbcTemplate db;
 RefundSync sync;RefundService refunds;RefundPullMessage pull;RefundConvertMessage convert;ConfiguredPushReader source;long order;
 @BeforeAll static void start(){Assumptions.assumeTrue(System.getenv("ORDER_TEST_URL")!=null);context=new AnnotationConfigApplicationContext(OrderIntakeMessageTest.Config.class);repo=context.getBean(OrderRepository.class);out=context.getBean(MessageOutbox.class);db=repo.db();}
 @AfterAll static void stop(){if(context!=null)context.close();}
 @BeforeEach void setup(){for(String table:Arrays.asList("oms_message_attempt","oms_message_outbox","oms_refund_event","oms_refund","oms_platform_refund_snapshot","oms_platform_refund","oms_refund_sync_item","oms_refund_sync","oms_refund_config","oms_order_line","oms_order","oms_platform_order"))db.update("DELETE FROM "+table+" WHERE company_code=?",C);refunds=new RefundService();refunds.repository=repo;sync=new RefundSync();sync.refunds=refunds;sync.catalog=mock(OrderCatalog.class);sync.reader=source=mock(ConfiguredPushReader.class);sync.logs=mock(RefundSyncLog.class);when(sync.logs.start(anyString(),anyMap(),anyString())).thenReturn(R.ok(m("id",1)));when(sync.logs.finish(anyString(),anyMap(),anyString())).thenReturn(R.ok(true));pull=new RefundPullMessage();pull.sync=sync;convert=new RefundConvertMessage();convert.refunds=refunds;convert.sync=sync;db.update("INSERT INTO oms_refund_config(company_code,channel_id,source_key,seller_nick,enabled,auto_convert,initial_time,cursor_time,updated_by) VALUES (?,1,'mq-refund','seller',0,1,'2026-10-01 00:00:00','2026-10-01 00:00:00','test')",C);}
 @AfterEach void cleanup(){sync.close();}
 long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE company_code=?",Long.class,C);}
 long task(){return number(sync.submit(C,m("channel_id",1,"mode","MANUAL","start_time","2026-10-01 00:00:00","end_time","2026-10-02 00:00:00","request_key",token()),"test"),"id");}
 Map<String,Object> notification(String kind,long id){return db.queryForMap("SELECT * FROM oms_message_outbox WHERE company_code=? AND message_type=? AND business_id=? ORDER BY id DESC LIMIT 1",C,kind,String.valueOf(id));}
 MessageRuntime runtime(MessageHandler handler){MessageRuntime r=new MessageRuntime();ReflectionTestUtils.setField(r,"outbox",out);ReflectionTestUtils.setField(r,"handlers",Collections.singletonList(handler));ReflectionTestUtils.setField(r,"tenants",mock(com.oms.common.tenant.TenantRouting.class));return r;}
 Map<String,Object> row(int i,int version,String status){String rid="98100000000000"+String.format("%04d",i),modified=String.format("2026-10-01 00:%02d:00",version);Map<String,Object> p=m("refund_id",rid,"tid","987654321012345678","oid","987654321012345679","seller_nick","seller","modified",modified,"refund_version",String.valueOf(version),"refund_fee","2.00","num",1,"status",status,"has_good_return",false,"reason","队列验收");return m("refund_id",rid,"tid",p.get("tid"),"oid",p.get("oid"),"seller_nick","seller","status",status,"modified",modified,"jdp_modified",modified,"jdp_response",OrderValues.encode(m("refund",p)));}
 long ingest(Map<String,Object> row){return number(refunds.tx().execute(s->refunds.ingest(C,1,"seller",row,"test")),"id");}
 void original(){String payload=TmallOrderParserTest.payload("25");long p=repo.insert("INSERT INTO oms_platform_order(company_code,channel_id,platform_tid,platform_status,trade_type,seller_nick,source_modified,payload_hash,raw_payload,processing_payload,processing_hash,conversion_status) VALUES (?,1,'987654321012345678','WAIT_SELLER_SEND_GOODS','fixed','seller','2026-10-01 00:00:00',?,?,?,?,'SUCCESS')",C,hash(payload),payload,payload,hash(payload));order=repo.insert("INSERT INTO oms_order(company_code,order_sn,channel_id,platform_order_id,platform_tid,inventory_status,payment,review_status) VALUES (?,'SO_REFUND_MQ',1,?,'987654321012345678','RESERVED',25,'APPROVED')",C,p);db.update("UPDATE oms_platform_order SET business_order_id=? WHERE company_code=? AND id=?",order,C,p);db.update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity) VALUES (?,?,'987654321012345679','A','fixture',5,25,5)",C,order);}
 @Test void taskAndNotificationRollbackTogether(){assertThrows(RuntimeException.class,()->out.tx(()->{task();throw new RuntimeException("rollback");}));assertEquals(0,count("oms_refund_sync"));assertEquals(0,count("oms_message_outbox"));}
 @Test void pageResumeAndLostAckDoNotDuplicateSourceOrTk(){long id=task();List<Map<String,Object>> first=new ArrayList<>();for(int i=1;i<=50;i++)first.add(row(i,1,"WAIT_SELLER_AGREE"));when(source.readRefund(anyString(),anyString(),anyString(),anyMap(),eq(50))).thenReturn(first,Collections.singletonList(row(51,1,"WAIT_SELLER_AGREE")));MessageRuntime r=runtime(pull);Map<String,Object> message=notification("REFUND_PULL",id);assertTrue(r.execute(C,message,"MQ"));assertEquals(50,count("oms_platform_refund"));assertEquals(0,count("oms_refund"));assertFalse(r.execute(C,message,"MQ"));db.update("UPDATE oms_message_outbox SET next_process_at=NOW() WHERE company_code=? AND event_id=?",C,message.get("event_id"));assertTrue(r.execute(C,out.row(C,text(message,"event_id")),"COMPENSATION"));assertEquals(51,count("oms_platform_refund"));assertEquals(51,db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox WHERE company_code=? AND message_type='REFUND_CONVERT'",Long.class,C));assertEquals("COMPLETED",sync.task(C,id).get("state"));assertFalse(r.execute(C,message,"MQ"));verify(source,times(2)).readRefund(anyString(),anyString(),anyString(),anyMap(),anyInt());}
 @Test void failedPageRollsBackFactsCursorAndConversionNotifications(){long id=task();Map<String,Object> bad=row(2,1,"WAIT_SELLER_AGREE");bad.put("seller_nick","other");when(source.readRefund(anyString(),anyString(),anyString(),anyMap(),anyInt())).thenReturn(Arrays.asList(row(1,1,"WAIT_SELLER_AGREE"),bad));assertEquals("WAITING",pull.handle(C,notification("REFUND_PULL",id)).state);assertEquals(0,count("oms_platform_refund"));assertEquals(1,count("oms_message_outbox"));assertEquals("2026-10-01 00:00:00",text(sync.rawTask(C,id,false),"page_time"));}
 @Test void refundBeforeOrderWaitsWithoutSpendingFailuresThenLinksOriginal(){long id=ingest(row(1,1,"WAIT_SELLER_AGREE"));Map<String,Object> m=notification("REFUND_CONVERT",id);MessageRuntime r=runtime(convert);db.update("UPDATE oms_message_outbox SET business_attempts=7 WHERE company_code=? AND event_id=?",C,m.get("event_id"));r.execute(C,out.row(C,text(m,"event_id")),"MQ");assertEquals("WAITING",out.row(C,text(m,"event_id")).get("process_state"));assertEquals(7,number(out.row(C,text(m,"event_id")),"business_attempts"));assertEquals(0,count("oms_refund"));original();db.update("UPDATE oms_message_outbox SET next_process_at=NOW() WHERE company_code=? AND event_id=?",C,m.get("event_id"));r.execute(C,out.row(C,text(m,"event_id")),"MQ");assertEquals("SUCCESS",out.row(C,text(m,"event_id")).get("process_state"));assertEquals(order,number(refunds.business(C,number(refunds.platform(C,id,false),"business_refund_id"),false),"order_id"));}
 @Test void duplicatesAndTwoRefundsForSameOrderProduceTwoDistinctTkWithoutStockChanges(){original();long one=ingest(row(1,1,"WAIT_SELLER_AGREE")),two=ingest(row(2,1,"WAIT_SELLER_AGREE"));assertEquals("SUCCESS",convert.handle(C,notification("REFUND_CONVERT",one)).state);assertEquals("SUCCESS",convert.handle(C,notification("REFUND_CONVERT",one)).state);assertEquals("SUCCESS",convert.handle(C,notification("REFUND_CONVERT",two)).state);assertEquals(2,count("oms_refund"));assertEquals(5,db.queryForObject("SELECT reserved_quantity FROM oms_order_line WHERE company_code=?",Integer.class,C));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM oms_refund WHERE company_code=? AND review_state='PENDING' AND goods_action='UNKNOWN'",Integer.class,C));}
 @Test void newerAndOlderSourceVersionsCannotRunStaleConversion(){long id=ingest(row(1,1,"WAIT_SELLER_AGREE"));Map<String,Object> old=notification("REFUND_CONVERT",id);ingest(row(1,2,"WAIT_SELLER_AGREE"));assertEquals("SUCCESS",convert.handle(C,old).state);assertEquals(0,count("oms_refund"));Map<String,Object> latest=notification("REFUND_CONVERT",id);ingest(row(1,1,"WAIT_SELLER_AGREE"));assertEquals(latest.get("event_id"),notification("REFUND_CONVERT",id).get("event_id"));}
 @Test void closureBeforeOriginalArrivesEndsPendingConversion(){long id=ingest(row(1,1,"WAIT_SELLER_AGREE"));ingest(row(1,2,"CLOSED"));assertEquals("SUCCESS",convert.handle(C,notification("REFUND_CONVERT",id)).state);assertEquals("SKIPPED",refunds.platform(C,id,false).get("conversion_state"));assertEquals(0,count("oms_refund"));}
 @Test void changedAdoptedPlanStaysBlockedAndDoesNotCreateAnotherTk(){original();long id=ingest(row(1,1,"WAIT_SELLER_AGREE"));convert.handle(C,notification("REFUND_CONVERT",id));long b=number(refunds.platform(C,id,false),"business_refund_id");db.update("UPDATE oms_refund SET approved_version=1,approved_hash='previous',approved_snapshot='{}',review_state='APPROVED' WHERE company_code=? AND id=?",C,b);ingest(row(1,2,"SUCCESS"));assertEquals("STALE",refunds.business(C,b,false).get("review_state"));assertEquals("BLOCKED",refunds.business(C,b,false).get("state"));assertEquals(1,count("oms_refund"));}
 @Test void shopLeaseWaitDoesNotConsumeRetryBudget(){long id=task(),p=ingest(row(1,1,"WAIT_SELLER_AGREE"));assertTrue(sync.claim(C,1,"other"));try{assertTrue(pull.handle(C,notification("REFUND_PULL",id)).preserveAttempts);assertTrue(convert.handle(C,notification("REFUND_CONVERT",p)).preserveAttempts);verifyNoInteractions(source);}finally{sync.release(C,1,"other");}}
 @Test void exhaustedReadKeepsCursorAndManualRetryLinksParent(){long id=task();Map<String,Object> old=notification("REFUND_PULL",id);db.update("UPDATE oms_message_outbox SET business_attempts=7 WHERE company_code=? AND event_id=?",C,old.get("event_id"));when(source.readRefund(anyString(),anyString(),anyString(),anyMap(),anyInt())).thenThrow(new RuntimeException(new java.net.SocketTimeoutException("fixture")));MessageRuntime r=runtime(pull);r.execute(C,out.row(C,text(old,"event_id")),"MQ");assertEquals("FAILED",sync.task(C,id).get("state"));r.retry(C,text(old,"event_id"),"test","来源已恢复");Map<String,Object> latest=notification("REFUND_PULL",id);assertEquals(old.get("event_id"),latest.get("parent_event_id"));assertEquals("2026-10-01 00:00:00",text(sync.rawTask(C,id,false),"page_time"));doReturn(Collections.emptyList()).when(source).readRefund(anyString(),anyString(),anyString(),anyMap(),anyInt());r.execute(C,latest,"MQ");assertEquals("COMPLETED",sync.task(C,id).get("state"));}
 @Test void manualRequestWorksWithAutoConversionDisabledAndIsIdempotent(){original();db.update("UPDATE oms_refund_config SET auto_convert=0 WHERE company_code=?",C);long id=ingest(row(1,1,"WAIT_SELLER_AGREE"));assertEquals(0,count("oms_message_outbox"));refunds.requestConvert(C,id,"test");refunds.requestConvert(C,id,"test");assertEquals(1,count("oms_message_outbox"));assertEquals("SUCCESS",convert.handle(C,notification("REFUND_CONVERT",id)).state);assertEquals(1,count("oms_refund"));}
 @Test void scannerPublishesOnlyAndNeverReadsSource(){task();ingest(row(1,1,"WAIT_SELLER_AGREE"));long before=count("oms_message_outbox");clearInvocations(source,sync.catalog);sync.shop(C,1);sync.shop(C,1);assertEquals(before,count("oms_message_outbox"));verifyNoInteractions(source,sync.catalog);}
 @Test void notificationAndDetailsAreCompanyScoped(){long t=task(),p=ingest(row(1,1,"WAIT_SELLER_AGREE"));assertThrows(IllegalArgumentException.class,()->sync.task("OTHER",t));assertThrows(IllegalArgumentException.class,()->refunds.platformDetail("OTHER",p));List<Map<String,Object>> rows=new ArrayList<>(Collections.singletonList(m("id",p)));repo.messageProgress("OTHER",rows,"REFUND_CONVERT");assertNull(rows.get(0).get("message"));}
 @Test void disabledCompanyCannotStartRefundIntake(){long t=task();MessageRuntime r=runtime(pull);com.oms.common.tenant.TenantRouting tenant=mock(com.oms.common.tenant.TenantRouting.class);when(tenant.open(C)).thenThrow(new IllegalArgumentException("disabled"));ReflectionTestUtils.setField(r,"tenants",tenant);Map<String,Object> m=notification("REFUND_PULL",t);assertThrows(IllegalArgumentException.class,()->r.execute(C,m,"MQ"));assertEquals("PENDING",out.row(C,text(m,"event_id")).get("process_state"));verifyNoInteractions(source);}
 @Test void failedAutomaticWindowCannotBeSkipped(){db.update("UPDATE oms_refund_config SET enabled=1,next_run=NOW() WHERE company_code=?",C);long id=task();db.update("UPDATE oms_refund_sync SET mode='AUTO',state='FAILED' WHERE company_code=? AND id=?",C,id);sync.shop(C,1);assertEquals(1,count("oms_refund_sync"));assertEquals("2026-10-01 00:00:00",text(sync.config(C,1,false),"cursor_time"));}
 @Test void failedConversionCanBeRepairedAndRetainsMessageParent(){original();db.update("DELETE FROM oms_order_line WHERE company_code=?",C);long p=ingest(row(1,1,"WAIT_SELLER_AGREE"));MessageRuntime r=runtime(convert);Map<String,Object> old=notification("REFUND_CONVERT",p);r.execute(C,old,"MQ");assertEquals("FAILED",refunds.platform(C,p,false).get("conversion_state"));db.update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment) VALUES (?,?,'987654321012345679','A','fixture',5,25)",C,order);r.retry(C,text(old,"event_id"),"test","已核对原平台子单");Map<String,Object> latest=notification("REFUND_CONVERT",p);assertEquals(old.get("event_id"),latest.get("parent_event_id"));r.execute(C,latest,"MQ");assertEquals("SUCCESS",refunds.platform(C,p,false).get("conversion_state"));assertEquals(1,count("oms_refund"));}
}
